const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function menuHTML(items,mobile=false,lang='en'){const path=p=>lang==='en'?p:p.replace(/^\/satin(?=\/|$)/,'/satin/'+lang);return items.filter(m=>m.active!==false).map(m=>m.groups?.length?(mobile?`<details><summary class="${m.key==='wraps'?'wraps-nav':''}">${esc(m.label)}</summary>${m.groups.map(g=>`<div><b>${esc(g.label)}</b>${g.links.filter(l=>l.active!==false).map(l=>`<a href="${esc(path(l.href))}"${/^all\b/i.test(l.label)?' class="all-link"':''}>${esc(l.label)}</a>`).join('')}</div>`).join('')}</details>`:`<button type="button" data-mega="${esc(m.key)}" aria-expanded="false">${esc(m.label)}<svg class="chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M6 9l6 6 6-6"/></svg></button>`):`<a class="${mobile?'plain-link':'studio-nav'}" href="${esc(path(m.href))}">${esc(m.label)}</a>`).join('');}

export function migrateNavigation(items){const rows=structuredClone(items);for(const m of rows){if(m.key==='apparel')for(const g of m.groups||[]){g.links=g.links.filter(l=>l.label!=='DTF print');for(const l of g.links)if(l.label==='DTF transfer')l.href='/satin/shop/dtf-transfers';}if(m.key==='print'){const g=m.groups.find(g=>g.label==='Large Format');if(g&&!g.links.some(l=>l.href.includes('poly-bag')))g.links.push({label:'Poly Bag Lawn Sign',href:'/satin/print-shop/large-format/poly-bag-lawn-sign',active:true});if(!m.groups.some(g=>g.links.some(l=>l.href.startsWith('/satin/print-shop/labels')))){const at=m.groups.findIndex(g=>g.label==='Help');m.groups.splice(at<0?m.groups.length:at,0,{label:'Labels & Stickers',links:[['Labels & stickers','/satin/print-shop/labels'],['Roll labels','/satin/print-shop/labels/roll-labels'],['Sticker sheets','/satin/print-shop/labels/sticker-sheets'],['Die-cut stickers','/satin/print-shop/labels/die-cut-stickers']].map(([label,href])=>({label,href,active:true}))});}}if(m.key==='shop'){const g=m.groups.find(g=>g.label==='Services');if(g)for(const [label,href] of [['Social Media','/satin/social-media-services'],['Videography','/satin/videography']])if(!g.links.some(l=>l.href===href))g.links.push({label,href,active:true});}}if(!rows.some(m=>m.key==='login'))rows.push({key:'login',label:'Log in',href:'/satin/login',active:true,groups:[]});return rows;}

/* Customer accounts: while signed in (non-secret "satin_acct" hint cookie, confirmed once per page by /api/customer/me), every "Log in" link becomes "My account". */
let accountCheck=null;
export function syncAccountLinks(root=document){const hint=/(?:^|;\s*)satin_acct=1/.test(document.cookie),lang=(location.pathname.match(/^\/satin\/(fa|fr|es)(?=\/|$)/)||[])[1],pre='/satin'+(lang?'/'+lang:''),label={fa:'حساب من',fr:'Mon compte',es:'Mi cuenta'}[lang]||'My account';const apply=on=>root.querySelectorAll('a[href]').forEach(a=>{if(a.closest('.nav'))return;const p=a.getAttribute('href').replace(/[?#].*$/,'');if(on&&/^\/satin(?:\/(?:fa|fr|es))?\/login\/?$/.test(p)){a.dataset.loginLabel=a.textContent;a.textContent=label;a.setAttribute('href',pre+'/account/');a.dataset.accountLink='';}else if(!on&&a.hasAttribute('data-account-link')){a.textContent=a.dataset.loginLabel||'Log in';a.setAttribute('href',pre+'/login/');a.removeAttribute('data-account-link');}});if(!hint)return;apply(true);accountCheck??=fetch('/api/customer/me',{credentials:'same-origin'}).then(r=>r.ok?r.json():null).then(d=>!!d?.customer).catch(()=>true);accountCheck.then(ok=>{if(!ok)apply(false);});}

/* ---------- Mobile header quick row + mobile menu drawer (pure HTML builders; same data as menuHTML) ---------- */
const NAV_ICONS={wraps:'<path d="M2 6h12v10H2zM14 9h4l3 3v4h-7"/><circle cx="6" cy="17.5" r="1.8"/><circle cx="17" cy="17.5" r="1.8"/>',print:'<path d="M6 9V3h12v6M6 18H4v-7h16v7h-2"/><path d="M7 14h10v7H7z"/>',apparel:'<path d="M8 3l-5 3 2 5 3-1v11h8V10l3 1 2-5-5-3a4 4 0 0 1-8 0z"/>',windows:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M12 3v18M4 12h16"/>',shop:'<path d="M5 8h14l-1 12H6z"/><path d="M9 8a3 3 0 0 1 6 0"/>',detailing:'<path d="M12 3s6 6.5 6 11a6 6 0 0 1-12 0c0-4.5 6-11 6-11z"/>',portfolio:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 15l5-4 4 3 3-2 6 4"/><circle cx="15.5" cy="9.5" r="1.5"/>',studio:'<path d="M14 4l6 6-8 8H6v-6z"/><path d="M3 21c2 0 3-1 3-3"/>',guides:'<path d="M4 5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0-2 2z"/><path d="M4 21V5M8 7h7"/>',login:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',dot:'<circle cx="12" cy="12" r="3.5"/>',chev:'<path d="M6 9l6 6 6-6"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',close:'<path d="M6 6l12 12M18 6L6 18"/>',cart:'<path d="M3 4h2l2.4 11.2a2 2 0 0 0 2 1.6h7.7a2 2 0 0 0 2-1.5L21 8H6.2"/><circle cx="10" cy="20" r="1.3"/><circle cx="17" cy="20" r="1.3"/>',phone:'<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>',wa:'<path d="M4 20l1.3-4A8 8 0 1 1 8 18.7z"/><path d="M9 9.5c0 3 2.5 5.5 5.5 5.5l1.2-1.4-2-1-1 .8a4 4 0 0 1-2.1-2.1l.8-1-1-2z"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3.5 3 14.5 0 18M12 3c-3 3.5-3 14.5 0 18"/>'};
const navIcon=(k,cls='d-ic')=>`<svg class="${cls}" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${NAV_ICONS[k]||NAV_ICONS.dot}</svg>`;
const NAV_TEXT={Menu:{fr:'Menu',es:'Menú',fa:'منو'},Close:{fr:'Fermer',es:'Cerrar',fa:'بستن'},'Close menu':{fr:'Fermer le menu',es:'Cerrar menú',fa:'بستن منو'},'Get a quote':{fr:'Demander un devis',es:'Solicitar presupuesto',fa:'درخواست قیمت'},Cart:{fr:'Panier',es:'Carrito',fa:'سبد'},'Log in':{fr:'Se connecter',es:'Iniciar sesión',fa:'ورود'},Call:{fr:'Appeler',es:'Llamar',fa:'تماس'},WhatsApp:{fr:'WhatsApp',es:'WhatsApp',fa:'واتس‌اپ'},Language:{fr:'Langue',es:'Idioma',fa:'زبان'},'Help & company':{fr:'Aide et entreprise',es:'Ayuda y empresa',fa:'راهنما و شرکت'},Guides:{fr:'Guides',es:'Guías',fa:'راهنماها'},About:{fr:'À propos',es:'Nosotros',fa:'درباره ما'},Reviews:{fr:'Avis',es:'Reseñas',fa:'نظرات'},FAQ:{fr:'FAQ',es:'Preguntas',fa:'سوالات متداول'},Contact:{fr:'Contact',es:'Contacto',fa:'تماس با ما'},'Track an order':{fr:'Suivre une commande',es:'Rastrear pedido',fa:'پیگیری سفارش'},'Quick links':{fr:'Accès rapide',es:'Accesos rápidos',fa:'دسترسی سریع'}};
const navT=(s,lang)=>NAV_TEXT[s]?.[lang]||s;
const LANG_NAMES=[['en','English','en-CA','ltr'],['fr','Français','fr-CA','ltr'],['es','Español','es','ltr'],['fa','فارسی','fa','rtl']];
function langPath(path,lang){return lang==='en'?path:String(path).replace(/^\/satin(?=\/|$|\?|#)/,'/satin/'+lang);}
function hubLink(m){const links=(m.groups||[]).flatMap(g=>(g.links||[]).filter(l=>l.active!==false));return (links.find(l=>/^all\b/i.test(l.label))||links[0]||m).href||m.href;}
/* Row of two equal buttons under the mobile header: Vehicle Wraps + Design Studio (labels/links from the admin menu). */
export function quickRowHTML(items,lang='en'){const act=(items||[]).filter(m=>m.active!==false);const w=act.find(m=>m.key==='wraps'),s=act.find(m=>m.key==='studio');const out=[];if(w)out.push(`<a class="mq mq-wraps" href="${esc(langPath(hubLink(w),lang))}">${navIcon('wraps','mq-ic')}<span>${esc(w.label)}</span></a>`);if(s)out.push(`<a class="mq mq-studio" href="${esc(langPath(s.href||'/satin/design-studio',lang))}">${navIcon('studio','mq-ic')}<span>${esc(s.label)}</span></a>`);return out.length?`<div class="wrap m-quick${out.length===1?' one':''}" data-m-quick>${out.join('')}</div>`:'';}
/* Mobile menu drawer content: accordion per top-level section, quick contact, language and account/cart/quote CTA. */
export function drawerHTML(items,o={}){const lang=o.lang||'en',t=s=>navT(s,lang),P=p=>esc(langPath(p,lang)),here=(o.path||'').replace(/\/$/,'');const act=(items||[]).filter(m=>m.active!==false&&m.key!=='login');
 const cur=h=>here&&langPath(String(h).replace(/[?#].*$/,'').replace(/\/$/,''),lang)===here;
 const nav=act.map(m=>{if(m.groups?.length){const open=m.groups.some(g=>(g.links||[]).some(l=>l.active!==false&&cur(l.href)));return `<details class="d-acc" name="satin-menu" data-key="${esc(m.key)}"${open?' open':''}><summary>${navIcon(m.key)}<span class="d-lbl">${esc(m.label)}</span>${navIcon('chev','d-chev')}</summary><div class="d-body">${m.groups.map(g=>{const links=(g.links||[]).filter(l=>l.active!==false);return links.length?`<div class="d-grp"><b>${esc(g.label)}</b>${links.map(l=>`<a href="${P(l.href)}"${/^all\b/i.test(l.label)?' class="all-link"':''}${cur(l.href)?' aria-current="page"':''}>${esc(l.label)}</a>`).join('')}</div>`:'';}).join('')}</div></details>`;}return `<a class="d-link${m.key==='studio'?' d-studio':''}" href="${P(m.href)}"${cur(m.href)?' aria-current="page"':''}>${navIcon(m.key)}<span class="d-lbl">${esc(m.label)}</span>${navIcon('arrow','d-go')}</a>`;}).join('');
 const extra=[['Guides','/satin/guides'],['About','/satin/about'],['Reviews','/satin/reviews'],['FAQ','/satin/faq'],['Contact','/satin/contact'],['Track an order','/satin/track']];
 const phone=String(o.phone||'').replace(/[^\d+]/g,''),tel=phone?(phone.startsWith('+')?phone:'+1'+phone):'';
 const langs=LANG_NAMES.map(([c,n,loc,dir])=>`<a href="${esc(o.langHref?o.langHref(c):langPath(here||'/satin',c))}" lang="${loc}" dir="${dir}" hreflang="${loc}"${c===lang?' aria-current="true"':''}>${n}</a>`).join('');
 return `<div class="scrim" data-close-drawer></div><div class="panel d-panel" role="dialog" aria-modal="true" aria-label="${esc(t('Menu'))}" tabindex="-1">
<div class="d-head"><a class="d-home" href="${P('/satin/')}"><img class="dlogo" src="${esc(o.logo||'/satin/img/logo.png')}" alt="Satin Graphic" width="483" height="78" decoding="async"></a><button type="button" class="d-close" data-close-drawer aria-label="${esc(t('Close menu'))}">${navIcon('close','')}<span>${esc(t('Close'))}</span></button></div>
<div class="d-scroll"><nav class="d-nav" aria-label="${esc(t('Menu'))}">${nav}</nav>
${extra.length?`<div class="d-sec"><b class="d-h">${esc(t('Help & company'))}</b><div class="d-chips">${extra.map(([l,h])=>`<a href="${P(h)}"${cur(h)?' aria-current="page"':''}>${esc(t(l))}</a>`).join('')}</div></div>`:''}
<div class="d-sec"><b class="d-h">${navIcon('globe','d-hic')}${esc(t('Language'))}</b><div class="d-langs">${langs}</div></div></div>
<div class="d-foot"><button type="button" class="btn block d-quote" data-quote="">${esc(t('Get a quote'))} ${navIcon('arrow','arrow')}</button>
<div class="d-tiles"><button type="button" class="d-tile" data-cart>${navIcon('cart','d-tic')}<span>${esc(t('Cart'))}</span><span class="badge" data-n="${o.cartCount||0}" data-cart-n>${o.cartCount||0}</span></button><a class="d-tile d-acct" href="${P('/satin/login/')}">${esc(t('Log in'))}</a>${tel?`<a class="d-tile" href="tel:${esc(tel)}">${navIcon('phone','d-tic')}<span>${esc(t('Call'))}</span></a>`:''}<a class="d-tile d-wa" href="https://wa.me/14163589740" target="_blank" rel="noopener">${navIcon('wa','d-tic')}<span>${esc(t('WhatsApp'))}</span></a></div></div></div>`;}
/* ---------- Mobile drawer behaviour (browser only): open/close, focus trap, Escape/back closes, body scroll lock ---------- */
let drawerBound=false,drawerEntry=false,ignorePop=false,pendingHref='',lastFocus=null;
const drawerEl=()=>document.querySelector('[data-drawer]');
export function isDrawerOpen(){return !!drawerEl()?.classList.contains('open');}
export function openDrawer(){const d=drawerEl();if(!d||d.classList.contains('open'))return;lastFocus=document.activeElement;d.classList.add('open');d.removeAttribute('aria-hidden');d.inert=false;document.documentElement.classList.add('drawer-open');document.querySelectorAll('[data-burger]').forEach(b=>b.setAttribute('aria-expanded','true'));try{if(!history.state?.satinDrawer){history.pushState({...(history.state||{}),satinDrawer:1},'',location.href);drawerEntry=true;}}catch{}const panel=d.querySelector('.panel');const cur=d.querySelector('.d-nav [aria-current]');if(cur)setTimeout(()=>cur.scrollIntoView({block:'center'}),0);setTimeout(()=>(d.querySelector('.d-close,[data-close-drawer]:not(.scrim)')||panel)?.focus({preventScroll:true}),30);}
/* history:false = only hide (used by the router when the page changes) */
export function closeDrawer({history:pop=true,restoreFocus=true}={}){const d=drawerEl();const wasOpen=d?.classList.contains('open');if(d){d.classList.remove('open');d.setAttribute('aria-hidden','true');d.inert=true;}document.documentElement.classList.remove('drawer-open');document.querySelectorAll('[data-burger]').forEach(b=>b.setAttribute('aria-expanded','false'));if(drawerEntry&&pop){drawerEntry=false;ignorePop=true;history.back();}else if(!pop)drawerEntry=false;if(wasOpen&&restoreFocus&&lastFocus&&document.contains(lastFocus))lastFocus.focus?.({preventScroll:true});lastFocus=null;}
function bindDrawer(){if(drawerBound)return;drawerBound=true;
 try{if(history.state?.satinDrawer){const {satinDrawer,...rest}=history.state;history.replaceState(Object.keys(rest).length?rest:null,'',location.href);}}catch{}
 document.addEventListener('click',e=>{const t=e.target;if(!t.closest)return;if(t.closest('[data-burger]')){e.preventDefault();isDrawerOpen()?closeDrawer():openDrawer();return;}if(t.closest('[data-close-drawer]')){closeDrawer();return;}
  const d=t.closest('[data-drawer]');if(!d||!isDrawerOpen())return;
  if(t.closest('[data-quote],[data-cart]')){closeDrawer({restoreFocus:false});return;}
  const a=t.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.hasAttribute('download')||(a.target&&a.target!=='_self'))return;
  const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;
  if(drawerEntry){e.preventDefault();e.stopImmediatePropagation();pendingHref=url.href;closeDrawer({restoreFocus:false});}else closeDrawer({restoreFocus:false});},true);
 addEventListener('popstate',e=>{if(ignorePop){ignorePop=false;e.stopImmediatePropagation();if(pendingHref){const h=pendingHref;pendingHref='';location.assign(h);}return;}if(isDrawerOpen()){drawerEntry=false;closeDrawer({history:false});e.stopImmediatePropagation();}},true);
 addEventListener('pageshow',e=>{if(e.persisted&&isDrawerOpen())closeDrawer({history:false,restoreFocus:false});});
 document.addEventListener('keydown',e=>{if(!isDrawerOpen())return;if(e.key==='Escape'){e.preventDefault();closeDrawer();return;}if(e.key!=='Tab')return;const panel=drawerEl().querySelector('.panel');const f=[...panel.querySelectorAll('a[href],button:not([disabled]),summary,select,input,[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetParent!==null||x===document.activeElement);if(!f.length)return;const first=f[0],last=f[f.length-1];if(!panel.contains(document.activeElement)){e.preventDefault();first.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}},true);
 /* one accordion group open at a time (fallback for browsers without <details name>) */
 document.addEventListener('toggle',e=>{const x=e.target;if(!(x instanceof HTMLDetailsElement)||!x.open||!x.matches('.d-acc'))return;x.closest('.d-nav')?.querySelectorAll('.d-acc[open]').forEach(o=>{if(o!==x)o.open=false;});},true);
 addEventListener('resize',()=>{if(isDrawerOpen()&&innerWidth>1100)closeDrawer();});
}
/* Builds the mobile quick row, the compact language code and the drawer from the admin menu; safe to call again (re-renders). */
export function mountMobileChrome(o={}){if(typeof document==='undefined')return;const items=o.items||[],lang=o.lang||'en',L=o.localize||(h=>h);
 for(const hdr of document.querySelectorAll('header.hdr')){hdr.querySelector('[data-m-quick]')?.remove();const q=quickRowHTML(items,lang);if(q)hdr.querySelector('.bar')?.insertAdjacentHTML('afterend',L(q));
  const lc=hdr.querySelector('.language-control');if(lc&&!lc.querySelector('.lang-code'))lc.insertAdjacentHTML('beforeend',`<span class="lang-code" aria-hidden="true">${({en:'EN',fr:'FR',es:'ES',fa:'FA'})[lang]||'EN'}</span>`);
  const b=hdr.querySelector('[data-burger]');if(b){b.setAttribute('aria-expanded',isDrawerOpen()?'true':'false');b.setAttribute('aria-haspopup','dialog');}
  const acct=hdr.querySelector('.login-btn');if(acct&&!acct.hasAttribute('aria-label'))acct.title=acct.textContent.trim();}
 const d=drawerEl();if(d){const open=d.classList.contains('open');const n=document.querySelector('.hdr [data-cart-n]')?.textContent||'0';d.innerHTML=L(drawerHTML(items,{...o,lang,cartCount:+n||0}));d.classList.add('m-drawer');if(!open){d.setAttribute('aria-hidden','true');d.inert=true;}}
 bindDrawer();}
